@VisibleForTesting static @Nullable Object singularFieldToProtoValue(SchemaInformation schemaInformation,FieldDescriptor fieldDescriptor,@Nullable Object value,boolean ignoreUnknownValues) throws SchemaConversionException {
  try {
    switch (schemaInformation.getType()) {
      case "INT64":case "INTEGER":    if (value instanceof String) {
          return Long.valueOf((String)value);
        }
        else if (value instanceof Integer || value instanceof Long) {
          return ((Number)value).longValue();
        }
        break;
      case "FLOAT64":case "FLOAT": if (value instanceof String) {
        return Double.valueOf((String)value);
      }
      else if (value instanceof Number) {
        return ((Number)value).doubleValue();
      }
      break;
      case "BOOLEAN":case "BOOL": if (value instanceof String) {
        return Boolean.valueOf((String)value);
      }
      else if (value instanceof Boolean) {
        return value;
      }
      break;
      case "BYTES": if (value instanceof String) {
        return ByteString.copyFrom(BaseEncoding.base64().decode((String)value));
      }
      else if (value instanceof byte[]) {
        return ByteString.copyFrom((byte[])value);
      }
      else if (value instanceof ByteString) {
        return value;
      }
      break;
      case "TIMESTAMP": if (value instanceof String) {
        try {
          return ChronoUnit.MICROS.between(Instant.EPOCH,Instant.parse((String)value));
        }
        catch (DateTimeParseException e) {
          return ChronoUnit.MICROS.between(Instant.EPOCH,Instant.ofEpochMilli(Long.parseLong((String)value)));
        }
      }
      else if (value instanceof Instant) {
        return ChronoUnit.MICROS.between(Instant.EPOCH,(Instant)value);
      }
      else if (value instanceof org.joda.time.Instant) {
        return ((org.joda.time.Instant)value).getMillis() * 1000L;
      }
      else if (value instanceof Integer || value instanceof Long) {
        return ((Number)value).longValue();
      }
      else if (value instanceof Double || value instanceof Float) {
        return BigDecimal.valueOf(((Number)value).doubleValue()).scaleByPowerOfTen(6).setScale(0,RoundingMode.HALF_UP).longValue();
      }
      break;
      case "DATE": if (value instanceof String) {
        return ((Long)LocalDate.parse((String)value).toEpochDay()).intValue();
      }
      else if (value instanceof LocalDate) {
        return ((Long)((LocalDate)value).toEpochDay()).intValue();
      }
      else if (value instanceof org.joda.time.LocalDate) {
        return Days.daysBetween(org.joda.time.Instant.EPOCH.toDateTime().toLocalDate(),(org.joda.time.LocalDate)value).getDays();
      }
      else if (value instanceof Integer || value instanceof Long) {
        return ((Number)value).intValue();
      }
      break;
      case "NUMERIC": if (value instanceof String) {
        return BigDecimalByteStringEncoder.encodeToNumericByteString(new BigDecimal((String)value));
      }
      else if (value instanceof BigDecimal) {
        return BigDecimalByteStringEncoder.encodeToNumericByteString(((BigDecimal)value));
      }
      else if (value instanceof Double || value instanceof Float) {
        return BigDecimalByteStringEncoder.encodeToNumericByteString(BigDecimal.valueOf(((Number)value).doubleValue()));
      }
      break;
      case "BIGNUMERIC": if (value instanceof String) {
        return BigDecimalByteStringEncoder.encodeToBigNumericByteString(new BigDecimal((String)value));
      }
      else if (value instanceof BigDecimal) {
        return BigDecimalByteStringEncoder.encodeToBigNumericByteString(((BigDecimal)value));
      }
      else if (value instanceof Double || value instanceof Float) {
        return BigDecimalByteStringEncoder.encodeToBigNumericByteString(BigDecimal.valueOf(((Number)value).doubleValue()));
      }
      break;
      case "DATETIME": if (value instanceof String) {
        return CivilTimeEncoder.encodePacked64DatetimeMicros(LocalDateTime.parse((String)value));
      }
      else if (value instanceof Number) {
        return ((Number)value).longValue();
      }
      else if (value instanceof LocalDateTime) {
        return CivilTimeEncoder.encodePacked64DatetimeMicros((LocalDateTime)value);
      }
      else if (value instanceof org.joda.time.LocalDateTime) {
        return CivilTimeEncoder.encodePacked64DatetimeMicros((org.joda.time.LocalDateTime)value);
      }
      break;
      case "TIME": if (value instanceof String) {
        return CivilTimeEncoder.encodePacked64TimeMicros(LocalTime.parse((String)value));
      }
      else if (value instanceof Number) {
        return ((Number)value).longValue();
      }
      else if (value instanceof LocalTime) {
        return CivilTimeEncoder.encodePacked64TimeMicros((LocalTime)value);
      }
      else if (value instanceof org.joda.time.LocalTime) {
        return CivilTimeEncoder.encodePacked64TimeMicros((org.joda.time.LocalTime)value);
      }
      break;
      case "STRING":case "JSON":case "GEOGRAPHY": return Preconditions.checkArgumentNotNull(value).toString();
      case "STRUCT":case "RECORD": if (value instanceof TableRow) {
        TableRow tableRow=(TableRow)value;
        return messageFromTableRow(schemaInformation,fieldDescriptor.getMessageType(),tableRow,ignoreUnknownValues);
      }
      else if (value instanceof AbstractMap) {
        AbstractMap<String,Object> map=((AbstractMap<String,Object>)value);
        return messageFromMap(schemaInformation,fieldDescriptor.getMessageType(),map,ignoreUnknownValues);
      }
      break;
    }
    throw new SchemaDoesntMatchException("Unexpected value :" + value + ", type: "+ (value == null ? "null" : value.getClass())+ ". Table field name: "+ schemaInformation.getFullName()+ ", type: "+ schemaInformation.getType());
  } catch (NumberFormatException | DateTimeParseException e) {
    throw new SchemaConversionException("Failed to convert value to proto field: " + e.getMessage(), e);
  }
}
